& .config-item-icon {
  block-size: 16px;
  inline-size: 16px;
  -moz-context-properties: fill, stroke, stroke-opacity;
  fill: light-dark(
    color-mix(in srgb, var(--color-text-secondary-light) 20%, transparent),
    color-mix(in srgb, var(--color-surface-deep-dark) 20%, transparent)
  );
  stroke: var(--color-text-secondary);

  .config-protocols & {
    block-size: 30px;
    inline-size: 30px;
  }
}

& .config-header,
& .config-detail {
  display: flex;
  flex-direction: row;
  align-items: center;
}

& .config-header {
  background-color: var(--color-primary-soft);
  padding: var(--space-step) var(--hub-space-small);
